//
//  RemoteCarouselRenderer.swift
//  Discbot
//
//  Self-contained WebGL carousel visualization for the remote web client.
//  It deliberately has no CDN or framework dependency so the controller UI
//  remains available on an isolated LAN.
//

import Foundation

enum RemoteCarouselRenderer {
    static let styles = #"""
.carousel-viewport{position:relative;margin-top:16px;padding:0;overflow:hidden;background:radial-gradient(circle at 48% 36%,#16283c 0,#0a111b 58%,#070b11 100%);border-color:#30445d;min-height:510px}.carousel-viewport:focus-within{border-color:#4f79a8}.carousel-scene-head{position:absolute;z-index:2;inset:16px 16px auto 16px;display:flex;align-items:flex-start;justify-content:space-between;gap:16px;pointer-events:none}.carousel-scene-head>*{pointer-events:auto}.carousel-scene-head h3{font-size:16px}.scene-kicker{display:flex;align-items:center;gap:8px;color:#b7c8dc;font-size:12px;font-weight:700}.scene-kicker:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 12px #51d393}.scene-actions{display:flex;gap:7px}.scene-actions button{padding:7px 10px;min-height:34px;background:#101a27cc;backdrop-filter:blur(10px);font-size:13px}.carousel-canvas{display:block;width:100%;height:510px;touch-action:none;cursor:grab;outline:none}.carousel-canvas.dragging{cursor:grabbing}.scene-help{position:absolute;z-index:2;left:16px;bottom:14px;padding:8px 11px;border:1px solid #2a3a4d;border-radius:9px;background:#08101acc;color:#a8b7c9;font-size:12px;pointer-events:none;backdrop-filter:blur(8px)}.scene-inspector{position:absolute;z-index:2;right:16px;bottom:14px;width:min(330px,calc(100% - 32px));padding:12px 14px;border:1px solid #35506e;border-radius:11px;background:#0c1622e8;box-shadow:0 12px 34px #0008;backdrop-filter:blur(12px)}.scene-inspector strong{display:block;font-size:17px}.scene-inspector p{margin:2px 0 0}.scene-slot-actions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin-top:11px}.scene-slot-actions button{padding:7px 5px;min-height:34px;font-size:12px}.scene-legend{display:flex;gap:13px;align-items:center;flex-wrap:wrap;margin:11px 2px 0;color:var(--muted);font-size:12px}.legend-item{display:flex;align-items:center;gap:6px}.legend-swatch{width:9px;height:9px;border-radius:3px;background:#7d91aa}.legend-swatch.audio{background:#b68cff}.legend-swatch.dvd{background:#ffbd69}.legend-swatch.data{background:#69a9ff}.legend-swatch.ripped{background:#51d393}.legend-swatch.active{background:#e6f5ff;box-shadow:0 0 8px #69a9ff}.visualization-note{margin:8px 2px 0;font-size:12px}.webgl-fallback{position:absolute;inset:0;display:grid;place-items:center;padding:60px;text-align:center;color:var(--muted)}@media(max-width:760px){.carousel-viewport{min-height:430px}.carousel-canvas{height:430px}.carousel-scene-head{inset:12px 12px auto}.scene-help{display:none}.scene-inspector{right:12px;bottom:12px;left:12px;width:auto}.scene-actions button{padding:7px 9px}.scene-slot-actions{grid-template-columns:repeat(2,minmax(0,1fr))}.scene-legend{gap:9px}.carousel-scene-head .muted{display:none}}
"""#

    static let markup = #"""
<section class="panel carousel-viewport" aria-label="Live 3D carousel visualization">
  <div class="carousel-scene-head">
    <div><div class="scene-kicker">Live inventory</div><h3>200-slot changer cutaway</h3><span class="muted">Visualization only</span></div>
    <div class="scene-actions"><button id="carouselMotionButton" type="button" aria-pressed="true" onclick="toggleCarouselMotion()">Pause motion</button><button type="button" onclick="resetCarouselView()">Reset view</button></div>
  </div>
  <canvas id="carouselCanvas" class="carousel-canvas" tabindex="0" aria-label="Interactive three-dimensional view of the 200-slot disc carousel. Drag to orbit, scroll to zoom, and select a disc for details."></canvas>
